#!/usr/bin/env node
/**
 * Build-time guard: verify prerender coverage.
 *
 * Fails the build loudly if any route registered in PRERENDERED_ROUTES
 * (src/lib/autoRoutes.ts, generated by scripts/generate-routes.cjs) does NOT
 * have a corresponding HTML file in dist/_prerender/.
 *
 * Why this exists (2026-07-29 incident):
 *   middleware.ts rewrites bot requests for any path in PRERENDERED_ROUTES to
 *   dist/_prerender/<path>.html. If that route is registered but the file was
 *   never generated by scripts/prerender.js, Vercel's rewrite target 404s.
 *   Regular browsers take a completely different code path (injectMetaIntoSpa,
 *   which always falls back to index.html) so they see a normal 200 page —
 *   this made the bug invisible unless you tested with a bot user-agent.
 *
 *   27 blog posts + all 25 programmatic SEO "combo" landing pages drifted out
 *   of sync this way and were returning a hard 404 to Googlebot/Bingbot while
 *   serving 200 to humans — a soft-cloaking bug that is the most likely cause
 *   of a Search Console traffic drop. This script makes that class of bug
 *   impossible to ship silently again: if route registration and prerendered
 *   HTML output ever drift apart, `npm run build` now fails instead of
 *   deploying broken routes.
 *
 * Run: node scripts/verify-prerender-coverage.cjs
 * Automatically run during: npm run build (final step)
 */

const fs = require('fs');
const path = require('path');

// This guard already runs immediately after prerender.js. Sanitize the actual
// error document first so every successful build also enforces consistent
// 404 crawler directives, removes canonical URLs, and strips page schema.
require('./postprocess-error-pages.cjs');

const PROJECT_ROOT = path.resolve(__dirname, '..');
const ROUTES_JSON = path.join(PROJECT_ROOT, 'scripts/routes.json');
const PRERENDER_DIR = path.join(PROJECT_ROOT, 'dist/_prerender');
const PRERENDER_MANIFEST_JSON = path.join(PRERENDER_DIR, 'manifest.json');
const APPROVED_SITEMAP_INVENTORY_JSON = path.join(PROJECT_ROOT, 'scripts/approved-sitemap-inventory.json');
const AUTO_ROUTES_TS = path.join(PROJECT_ROOT, 'src/lib/autoRoutes.ts');
const BLOG_POSTS_TS = path.join(PROJECT_ROOT, 'src/data/blogPosts.ts');
const MAIN_TSX = path.join(PROJECT_ROOT, 'src/main.tsx');
const BLOG_POST_PAGE_TSX = path.join(PROJECT_ROOT, 'src/pages/BlogPost.tsx');
const VERCEL_JSON = path.join(PROJECT_ROOT, 'vercel.json');
const SITE_URL = 'https://luxemia.shop';
const APPROVED_PRODUCT_HANDLES = new Set(
  JSON.parse(fs.readFileSync(APPROVED_SITEMAP_INVENTORY_JSON, 'utf8')).paths
    .filter((route) => route.startsWith('/product/'))
    .map((route) => route.slice('/product/'.length)),
);
const AUTHOR_ROUTE = '/authors/luxemia-editorial-team';
const BLOG_TOPIC_HUBS = [
  '/blog/indian-wedding-guest-attire',
  '/blog/indian-textiles-and-embroidery',
  '/blog/weddings-festivals',
  '/blog/fit-sizing-and-garment-care',
  '/blog/designer-profiles',
  '/blog/cultural-context',
];
const LEGACY_AUTHOR_ROUTES = [
  '/authors/ananya-iyer',
  '/authors/meera-kapoor',
  '/authors/rajesh-sharma',
  '/authors/priya-nair',
];
const LEGACY_AUTHOR_NAMES = ['Ananya Iyer', 'Meera Kapoor', 'Rajesh Sharma', 'Priya Nair'];
const SEO_ARCHITECTURE = JSON.parse(
  fs.readFileSync(path.join(PROJECT_ROOT, 'src/config/seoArchitecture.json'), 'utf8'),
);
const COMMERCIAL_COLLECTIONS = [
  { route: '/collections/bridal-lehengas', category: 'lehengas' },
  { route: '/collections/party-wear-lehengas', category: 'lehengas' },
  { route: '/collections/wedding-sarees', category: 'sarees' },
  { route: '/collections/designer-sarees', category: 'sarees' },
  { route: '/collections/sharara-suits', category: 'suits' },
  { route: '/collections/gharara-suits', category: 'suits' },
  { route: '/collections/anarkali-suits', category: 'suits' },
];

function routeToFilePath(routePath) {
  if (routePath === '/') {
    return path.join(PRERENDER_DIR, 'index.html');
  }
  const parts = routePath.slice(1); // remove leading /
  return path.join(PRERENDER_DIR, `${parts}.html`);
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function extractQuotedValues(source) {
  return [...source.matchAll(/['"]([^'"]+)['"]/g)].map((match) => match[1]);
}

function parsePublishedBlogSlugs() {
  if (!fs.existsSync(BLOG_POSTS_TS)) {
    throw new Error(`${BLOG_POSTS_TS} not found`);
  }
  const source = fs.readFileSync(BLOG_POSTS_TS, 'utf8');
  const block = source.match(/PUBLISHED_BLOG_SLUGS\s*=\s*\[([\s\S]*?)\]\s*as const/);
  if (!block) {
    throw new Error(`PUBLISHED_BLOG_SLUGS was not found in ${BLOG_POSTS_TS}`);
  }
  const slugs = extractQuotedValues(block[1]);
  if (slugs.length === 0) {
    throw new Error(`PUBLISHED_BLOG_SLUGS is empty in ${BLOG_POSTS_TS}`);
  }
  const duplicates = slugs.filter((slug, index) => slugs.indexOf(slug) !== index);
  if (duplicates.length > 0) {
    throw new Error(`PUBLISHED_BLOG_SLUGS contains duplicate(s): ${[...new Set(duplicates)].join(', ')}`);
  }
  return slugs;
}

function parseAutoRoutes() {
  if (!fs.existsSync(AUTO_ROUTES_TS)) {
    throw new Error(`${AUTO_ROUTES_TS} not found`);
  }
  const source = fs.readFileSync(AUTO_ROUTES_TS, 'utf8');
  const block = source.match(/PRERENDERED_ROUTES[\s\S]*?new Set\(\s*\[([\s\S]*?)\]\s*\)/);
  if (!block) {
    throw new Error(`PRERENDERED_ROUTES could not be parsed from ${AUTO_ROUTES_TS}`);
  }
  return extractQuotedValues(block[1]);
}

function getHtmlAttribute(tag, attribute) {
  const escapedAttribute = attribute.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = tag.match(new RegExp(`\\b${escapedAttribute}\\s*=\\s*(["'])(.*?)\\1`, 'i'));
  return match?.[2] ?? null;
}

function collectSchemaNodesByType(value, schemaType, nodes = []) {
  if (Array.isArray(value)) {
    for (const entry of value) collectSchemaNodesByType(entry, schemaType, nodes);
    return nodes;
  }
  if (!value || typeof value !== 'object') return nodes;

  const types = Array.isArray(value['@type']) ? value['@type'] : [value['@type']];
  if (types.includes(schemaType)) nodes.push(value);
  for (const nestedValue of Object.values(value)) {
    collectSchemaNodesByType(nestedValue, schemaType, nodes);
  }
  return nodes;
}

function parseJsonLdScripts(html, route, failures) {
  const parsed = [];
  for (const match of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
    const attributes = match[1];
    if (getHtmlAttribute(attributes, 'type')?.toLowerCase() !== 'application/ld+json') continue;
    try {
      parsed.push({ attributes, schema: JSON.parse(match[2]) });
    } catch (error) {
      failures.push(`${route}: invalid JSON-LD (${error.message})`);
    }
  }
  return parsed;
}

function verifyJulyRegressionGuards(routes) {
  const failures = [];
  const routeSet = new Set(routes);
  const duplicateRoutes = routes.filter((route, index) => routes.indexOf(route) !== index);
  if (duplicateRoutes.length > 0) {
    failures.push(`scripts/routes.json contains duplicate(s): ${[...new Set(duplicateRoutes)].join(', ')}`);
  }

  let autoRoutes = [];
  try {
    autoRoutes = parseAutoRoutes();
  } catch (error) {
    failures.push(error.message);
  }
  if (autoRoutes.length > 0) {
    const autoRouteSet = new Set(autoRoutes);
    const missingFromAutoRoutes = routes.filter((route) => !autoRouteSet.has(route));
    const missingFromRoutesJson = autoRoutes.filter((route) => !routeSet.has(route));
    if (missingFromAutoRoutes.length > 0) {
      failures.push(`src/lib/autoRoutes.ts is missing manifest route(s): ${missingFromAutoRoutes.join(', ')}`);
    }
    if (missingFromRoutesJson.length > 0) {
      failures.push(`scripts/routes.json is missing auto route(s): ${missingFromRoutesJson.join(', ')}`);
    }
    if (autoRoutes.length !== autoRouteSet.size) {
      failures.push('src/lib/autoRoutes.ts contains duplicate routes');
    }
  }

  let publishedSlugs = [];
  try {
    publishedSlugs = parsePublishedBlogSlugs();
  } catch (error) {
    failures.push(error.message);
  }
  const publishedRoutes = publishedSlugs.map((slug) => `/blog/${slug}`);
  const publishedRouteSet = new Set(publishedRoutes);
  for (const route of publishedRoutes) {
    if (!routeSet.has(route)) failures.push(`${route}: published source article is absent from routes.json`);
  }
  for (const route of BLOG_TOPIC_HUBS) {
    if (!routeSet.has(route)) failures.push(`${route}: required blog topic hub is absent from routes.json`);
  }
  const unknownBlogRoutes = routes.filter(
    (route) => route.startsWith('/blog/')
      && !publishedRouteSet.has(route)
      && !BLOG_TOPIC_HUBS.includes(route),
  );
  if (unknownBlogRoutes.length > 0) {
    failures.push(`routes.json contains blog article route(s) outside PUBLISHED_BLOG_SLUGS: ${unknownBlogRoutes.join(', ')}`);
  }

  if (!routeSet.has(AUTHOR_ROUTE)) {
    failures.push(`${AUTHOR_ROUTE}: factual author route is absent from routes.json`);
  } else {
    const authorHtml = fs.readFileSync(routeToFilePath(AUTHOR_ROUTE), 'utf8');
    const metaTags = [...authorHtml.matchAll(/<meta\b[^>]*>/gi)].map((match) => match[0]);
    const robotsTags = metaTags.filter(
      (tag) => getHtmlAttribute(tag, 'name')?.toLowerCase() === 'robots',
    );
    const robotsContent = robotsTags.length === 1 ? getHtmlAttribute(robotsTags[0], 'content') : null;
    if (robotsTags.length !== 1 || !robotsContent || !/\bindex\b/i.test(robotsContent) || /\bnoindex\b/i.test(robotsContent)) {
      failures.push(`${AUTHOR_ROUTE}: expected one indexable robots directive`);
    }

    const canonicalTags = [...authorHtml.matchAll(/<link\b[^>]*>/gi)]
      .map((match) => match[0])
      .filter((tag) => getHtmlAttribute(tag, 'rel')?.toLowerCase() === 'canonical');
    const canonical = canonicalTags.length === 1 ? getHtmlAttribute(canonicalTags[0], 'href') : null;
    if (canonical !== `${SITE_URL}${AUTHOR_ROUTE}`) {
      failures.push(`${AUTHOR_ROUTE}: expected one self-referencing canonical`);
    }
    if (!authorHtml.includes('<h1>LuxeMia Editorial Team</h1>')) {
      failures.push(`${AUTHOR_ROUTE}: factual author prerender is missing its H1`);
    }
  }

  for (const route of publishedRoutes) {
    if (!routeSet.has(route)) continue;
    const html = fs.readFileSync(routeToFilePath(route), 'utf8');
    const jsonLdScripts = parseJsonLdScripts(html, route, failures);
    const blogPostings = jsonLdScripts.flatMap(({ attributes, schema }) =>
      collectSchemaNodesByType(schema, 'BlogPosting').map((node) => ({ attributes, node })),
    );
    if (blogPostings.length !== 1) {
      failures.push(`${route}: expected exactly one prerendered BlogPosting schema, found ${blogPostings.length}`);
    } else {
      const [{ attributes, node }] = blogPostings;
      if (!/\bdata-prerender-schema(?:\s|=|$)/i.test(attributes)) {
        failures.push(`${route}: BlogPosting schema is not marked data-prerender-schema for hydration cleanup`);
      }
      const authors = Array.isArray(node.author) ? node.author : [node.author];
      const hasFactualAuthor = authors.some(
        (author) => author?.name === 'LuxeMia Editorial Team'
          && author?.url === `${SITE_URL}${AUTHOR_ROUTE}`,
      );
      if (!hasFactualAuthor) {
        failures.push(`${route}: BlogPosting does not reference the factual editorial-team author`);
      }
    }
    for (const legacyRoute of LEGACY_AUTHOR_ROUTES) {
      if (html.includes(legacyRoute)) failures.push(`${route}: prerender still links to ${legacyRoute}`);
    }
    for (const legacyName of LEGACY_AUTHOR_NAMES) {
      if (html.includes(legacyName)) failures.push(`${route}: prerender still names fabricated author ${legacyName}`);
    }
  }

  const mainSource = fs.readFileSync(MAIN_TSX, 'utf8');
  const cleanupIndex = mainSource.indexOf('script[data-prerender-schema]');
  const createRootIndex = mainSource.indexOf('createRoot(');
  const cleanupSection = cleanupIndex >= 0 && createRootIndex > cleanupIndex
    ? mainSource.slice(cleanupIndex, createRootIndex)
    : '';
  if (!cleanupSection.includes('.remove()')) {
    failures.push('src/main.tsx must remove data-prerender-schema scripts before createRoot()');
  }

  const blogPostPageSource = fs.readFileSync(BLOG_POST_PAGE_TSX, 'utf8');
  const hydratedBlogPostingCount = (
    blogPostPageSource.match(/["']@type["']\s*:\s*["']BlogPosting["']/g) || []
  ).length;
  if (hydratedBlogPostingCount !== 1) {
    failures.push(`src/pages/BlogPost.tsx must define exactly one hydrated BlogPosting schema, found ${hydratedBlogPostingCount}`);
  }
  if (!blogPostPageSource.includes(`${SITE_URL}${AUTHOR_ROUTE}`)) {
    failures.push('src/pages/BlogPost.tsx does not reference the factual editorial-team author URL');
  }

  let vercelConfig;
  try {
    vercelConfig = JSON.parse(fs.readFileSync(VERCEL_JSON, 'utf8'));
  } catch (error) {
    failures.push(`vercel.json could not be parsed (${error.message})`);
  }
  const redirects = Array.isArray(vercelConfig?.redirects) ? vercelConfig.redirects : [];
  for (const legacyRoute of LEGACY_AUTHOR_ROUTES) {
    const matchingRedirects = redirects.filter((redirect) => redirect.source === legacyRoute);
    if (
      matchingRedirects.length !== 1
      || matchingRedirects[0].destination !== AUTHOR_ROUTE
      || matchingRedirects[0].statusCode !== 301
    ) {
      failures.push(`${legacyRoute}: expected one 301 redirect to ${AUTHOR_ROUTE}`);
    }
    if (routeSet.has(legacyRoute)) {
      failures.push(`${legacyRoute}: legacy fabricated author remains in routes.json`);
    }
    if (fs.existsSync(routeToFilePath(legacyRoute))) {
      failures.push(`${legacyRoute}: legacy fabricated author still has prerendered HTML`);
    }
  }

  return { failures, publishedCount: publishedRoutes.length };
}

function parseCommercialCollectionHtml(route, category) {
  const filePath = routeToFilePath(route);
  const html = fs.readFileSync(filePath, 'utf8');
  const payloadMatch = html.match(/window\.__INITIAL_DATA__\s*=\s*([\s\S]*?);<\/script>/);
  if (!payloadMatch) return `${route}: missing window.__INITIAL_DATA__ payload`;

  let payload;
  try {
    payload = JSON.parse(payloadMatch[1]);
  } catch (error) {
    return `${route}: invalid window.__INITIAL_DATA__ JSON (${error.message})`;
  }

  const payloadHandles = (payload.products || [])
    .map((product) => product?.node?.handle)
    .filter(Boolean);
  if (payload.category !== category) {
    return `${route}: hydration category is '${payload.category || '(missing)'}', expected '${category}'`;
  }
  if (payloadHandles.length === 0) return `${route}: hydration payload has no products`;

  const linkedHandles = [...html.matchAll(/href="\/product\/([^"?#]+)"/g)].map((match) => match[1]);
  if (linkedHandles.length === 0) return `${route}: prerendered HTML has no product links`;

  const schemas = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)]
    .map((match) => {
      try {
        return JSON.parse(match[1]);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
  const itemList = schemas.find((schema) => schema['@type'] === 'ItemList');
  if (!itemList) return `${route}: missing valid ItemList JSON-LD`;

  const itemListHandles = (itemList.itemListElement || [])
    .map((entry) => (entry?.url || entry?.item?.url)?.match(/\/product\/([^/?#]+)$/)?.[1])
    .filter(Boolean);
  const expected = JSON.stringify(payloadHandles);
  const cardHandles = linkedHandles.slice(0, payloadHandles.length);
  if (JSON.stringify(cardHandles) !== expected) {
    return `${route}: first product-card links do not match the hydration payload`;
  }
  const overflowHandles = linkedHandles.slice(payloadHandles.length);
  const invalidOverflowHandles = overflowHandles.filter((handle) => !APPROVED_PRODUCT_HANDLES.has(handle));
  if (invalidOverflowHandles.length > 0) {
    return `${route}: overflow links include product(s) outside the approved sitemap inventory: ${[...new Set(invalidOverflowHandles)].join(', ')}`;
  }
  if (new Set(linkedHandles).size !== linkedHandles.length) {
    return `${route}: product-card and overflow links contain duplicate handles`;
  }
  if (JSON.stringify(itemListHandles) !== expected || itemList.numberOfItems !== payloadHandles.length) {
    return `${route}: ItemList products do not match the hydration payload`;
  }

  return null;
}

function decodeHtmlText(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_match, codePoint) => String.fromCodePoint(Number(codePoint)))
    .replace(/\s+/g, ' ')
    .trim();
}

function groupProductRecords(records, key) {
  const groups = new Map();
  for (const record of records) {
    const value = record[key];
    if (!value) continue;
    const normalized = value.toLowerCase().replace(/\s+/g, ' ').trim();
    const group = groups.get(normalized) || [];
    group.push(record);
    groups.set(normalized, group);
  }
  return [...groups.values()].filter((group) => group.length > 1);
}

function verifyProductDiscoveryAndDuplicateSignals() {
  const failures = [];
  const warnings = [];
  if (!fs.existsSync(PRERENDER_MANIFEST_JSON)) {
    return {
      failures: [`${path.relative(PROJECT_ROOT, PRERENDER_MANIFEST_JSON)} is missing`],
      warnings,
      approvedProductCount: 0,
    };
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(PRERENDER_MANIFEST_JSON, 'utf8'));
  } catch (error) {
    return {
      failures: [`${path.relative(PROJECT_ROOT, PRERENDER_MANIFEST_JSON)} is invalid JSON (${error.message})`],
      warnings,
      approvedProductCount: 0,
    };
  }

  const currentApprovedHandles = new Set(
    (manifest.productHandles || []).filter((handle) => APPROVED_PRODUCT_HANDLES.has(handle)),
  );
  const inboundSources = new Map(
    [...currentApprovedHandles].map((handle) => [handle, new Set()]),
  );
  const productRecords = [];

  for (const route of manifest.routes || []) {
    const filePath = routeToFilePath(route);
    if (!fs.existsSync(filePath)) {
      failures.push(`${route}: prerender manifest route has no HTML file`);
      continue;
    }
    const html = fs.readFileSync(filePath, 'utf8');
    const linkedHandles = [...html.matchAll(/href=["'](?:https:\/\/luxemia\.shop)?\/product\/([^"'?#]+)(?:[?#][^"']*)?["']/gi)]
      .map((match) => match[1]);
    for (const handle of new Set(linkedHandles)) {
      if (!currentApprovedHandles.has(handle) || route === `/product/${handle}`) continue;
      inboundSources.get(handle).add(route);
    }

    if (!route.startsWith('/product/') || !currentApprovedHandles.has(route.slice('/product/'.length))) {
      continue;
    }

    const title = decodeHtmlText(html.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i)?.[1]);
    const h1 = decodeHtmlText(html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1]);
    const descriptionTag = [...html.matchAll(/<meta\b[^>]*>/gi)]
      .map((match) => match[0])
      .find((tag) => getHtmlAttribute(tag, 'name')?.toLowerCase() === 'description');
    const metaDescription = decodeHtmlText(descriptionTag ? getHtmlAttribute(descriptionTag, 'content') : '');
    const productDescription = decodeHtmlText(
      html.match(/<h2>Product Description<\/h2>\s*<p>([\s\S]*?)<\/p>/i)?.[1],
    );
    const styleReference = decodeHtmlText(
      html.match(/<dt>Style Reference<\/dt>\s*<dd>([\s\S]*?)<\/dd>/i)?.[1],
    );
    productRecords.push({ route, title, h1, metaDescription, productDescription, styleReference });
  }

  for (const [handle, sources] of inboundSources) {
    if (sources.size < 2) {
      failures.push(
        `/product/${handle}: expected at least two distinct crawlable inbound sources, found ${sources.size}${sources.size ? ` (${[...sources].join(', ')})` : ''}`,
      );
    }
  }

  const duplicateTitleGroups = groupProductRecords(productRecords, 'title');
  for (const group of duplicateTitleGroups) {
    const distinctH1s = new Set(group.map((record) => record.h1.toLowerCase()));
    const details = group
      .map((record) => `${record.route}${record.styleReference ? ` [${record.styleReference}]` : ' [no style reference]'}`)
      .join(', ');
    if (distinctH1s.size > 1) {
      failures.push(`final product title truncation collision across distinct H1s: '${group[0].title}' — ${details}`);
    } else {
      warnings.push(`unresolved same-title product cluster: '${group[0].title}' — ${details}`);
    }
  }

  for (const group of groupProductRecords(productRecords, 'metaDescription')) {
    warnings.push(`unresolved duplicate meta-description cluster (${group.length}): ${group.map((record) => record.route).join(', ')}`);
  }
  for (const group of groupProductRecords(productRecords, 'productDescription')) {
    warnings.push(`unresolved duplicate product-description cluster (${group.length}): ${group.map((record) => record.route).join(', ')}`);
  }

  return {
    failures,
    warnings,
    approvedProductCount: currentApprovedHandles.size,
  };
}

function main() {
  if (!fs.existsSync(ROUTES_JSON)) {
    console.error(`[verify-prerender-coverage] ${ROUTES_JSON} not found — did generate-routes.cjs run?`);
    process.exit(1);
  }
  if (!fs.existsSync(PRERENDER_DIR)) {
    console.error(`[verify-prerender-coverage] ${PRERENDER_DIR} not found — did prerender.js run?`);
    process.exit(1);
  }

  const routes = JSON.parse(fs.readFileSync(ROUTES_JSON, 'utf8'));
  const missing = [];

  for (const route of routes) {
    const filePath = routeToFilePath(route);
    if (!fs.existsSync(filePath)) {
      missing.push({ route, filePath });
    }
  }

  if (missing.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${missing.length} route(s) in PRERENDERED_ROUTES have no prerendered HTML file.`);
    console.error('[verify-prerender-coverage] These routes would return a bot-only 404 in production (soft cloaking) — see the 2026-07-29 incident notes in this script.');
    console.error('[verify-prerender-coverage] Missing routes:');
    for (const { route, filePath } of missing) {
      console.error(`  ${route}  →  ${path.relative(PROJECT_ROOT, filePath)}`);
    }
    console.error('\n[verify-prerender-coverage] Fix: either (a) add/verify the route in scripts/prerender.js so it generates HTML, or (b) remove the route from scripts/generate-routes.cjs if it should not be prerendered.\n');
    process.exit(1);
  }

  const julyRegressionGuards = verifyJulyRegressionGuards(routes);
  if (julyRegressionGuards.failures.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${julyRegressionGuards.failures.length} source/manifest/blog-author regression guard(s) failed.`);
    for (const failure of julyRegressionGuards.failures) console.error(`  ${failure}`);
    process.exit(1);
  }

  const seoArchitectureFailures = [];
  for (const [route, seo] of Object.entries(SEO_ARCHITECTURE.routes)) {
    const filePath = routeToFilePath(route);
    if (!fs.existsSync(filePath)) {
      seoArchitectureFailures.push(`${route}: shared SEO route has no prerendered HTML`);
      continue;
    }
    const html = fs.readFileSync(filePath, 'utf8');
    if (!html.includes(`<h1>${escapeHtml(seo.h1)}</h1>`)) {
      seoArchitectureFailures.push(`${route}: prerendered H1 does not match shared SEO architecture`);
    }
  }

  for (const route of routes) {
    const html = fs.readFileSync(routeToFilePath(route), 'utf8');
    if (/href=["']\/(?:lehengas|sarees|suits|menswear|jewelry)\?sub=/i.test(html)) {
      seoArchitectureFailures.push(`${route}: prerendered HTML links to a noindex facet URL`);
    }
  }

  const homepageHtml = fs.readFileSync(routeToFilePath('/'), 'utf8');
  if (!homepageHtml.includes(`<title>${escapeHtml(SEO_ARCHITECTURE.routes['/'].title)}</title>`)) {
    seoArchitectureFailures.push('/: prerendered title does not match the shared branded homepage title');
  }
  if (/SearchAction|urlTemplate/.test(homepageHtml)) {
    seoArchitectureFailures.push('/: homepage still advertises a search action without an indexable search route');
  }
  const homepageLogoCount = (homepageHtml.match(/"logo"\s*:\s*"https:\/\/luxemia\.shop\/og-image\.jpg"/g) || []).length;
  if (homepageLogoCount !== 1) {
    seoArchitectureFailures.push(`/: expected one consolidated Organization/OnlineStore logo reference, found ${homepageLogoCount}`);
  }

  if (seoArchitectureFailures.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${seoArchitectureFailures.length} SEO architecture check(s) failed.`);
    for (const failure of seoArchitectureFailures) console.error(`  ${failure}`);
    process.exit(1);
  }

  const invalidCommercialCollections = COMMERCIAL_COLLECTIONS
    .map(({ route, category }) => parseCommercialCollectionHtml(route, category))
    .filter(Boolean);
  if (invalidCommercialCollections.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${invalidCommercialCollections.length} commercial collection prerender(s) are incomplete.`);
    for (const failure of invalidCommercialCollections) console.error(`  ${failure}`);
    process.exit(1);
  }

  const productDiscoverySignals = verifyProductDiscoveryAndDuplicateSignals();
  if (productDiscoverySignals.failures.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${productDiscoverySignals.failures.length} product discovery/title check(s) failed.`);
    for (const failure of productDiscoverySignals.failures) console.error(`  ${failure}`);
    process.exit(1);
  }
  if (productDiscoverySignals.warnings.length > 0) {
    console.warn(`\n[verify-prerender-coverage] REVIEW: ${productDiscoverySignals.warnings.length} unresolved duplicate product-content cluster(s).`);
    for (const warning of productDiscoverySignals.warnings) console.warn(`  ${warning}`);
  }

  const productDir = path.join(PRERENDER_DIR, 'product');
  const legacyCopyFailures = fs.existsSync(productDir)
    ? fs.readdirSync(productDir)
      .filter((name) => name.endsWith('.html'))
      .filter((name) => {
        const html = fs.readFileSync(path.join(productDir, name), 'utf8');
        return /5-day express delivery to USA and Canada|FAQQ\s*:/i.test(html)
          || /<h1[^>]*>[^<]*\|\s*luxemia\.shop\s*<\/h1>/i.test(html)
          || /\bIncludes:\s*[^.<]{0,120}(?:\$|\bapproved\b|\bpricing\b|\bfee\b|\bcharge\b|\bservice\b|\btier\b)/i.test(html);
      })
    : [];
  if (legacyCopyFailures.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${legacyCopyFailures.length} product prerender(s) contain obsolete supplier copy, a branded-domain H1, or pricing/service text mislabeled as included pieces.`);
    for (const name of legacyCopyFailures.slice(0, 30)) console.error(`  /product/${name.replace(/\.html$/, '')}`);
    process.exit(1);
  }

  console.log(`[verify-prerender-coverage] OK — all ${routes.length} routes have clean HTML; ${julyRegressionGuards.publishedCount} published articles, ${BLOG_TOPIC_HUBS.length} blog hubs, the factual author route, hydration-safe BlogPosting schema, and legacy-author redirects are aligned; all ${COMMERCIAL_COLLECTIONS.length} commercial collections have aligned product payloads, links, and ItemList schema; ${productDiscoverySignals.approvedProductCount} approved products have at least two crawlable inbound sources.`);
}

main();
